function getSelectedSphere(mouseX, mouseY, spheres, camera) {
    let closest = null;
    let closestDist = Infinity;

    for (const sphere of spheres) {
        // Project sphere center to screen
        const screen = projectToScreen(sphere.position, camera);
        if (!screen) continue; // Behind camera

        // 2D distance: mouse to projected center
        const dx = mouseX - screen.x;
        const dy = mouseY - screen.y;
        const dist = Math.sqrt(dx * dx + dy * dy);

        // Effective radius includes visual size + touch margin
        const visualRadius = sphere.radius * screen.scale;
        const hitRadius = Math.max(visualRadius + 15, 40); // Min 40px

        if (dist < hitRadius && dist < closestDist) {
            closest = sphere;
            closestDist = dist;
        }
    }
    return closest;
}

function projectToScreen(worldPos, camera) {
    // Transform to camera space
    const dx = worldPos.x - camera.x;
    const dy = worldPos.y - camera.y;
    const dz = worldPos.z - camera.z;

    // Dot with camera basis vectors
    const viewZ = dx * camera.forward.x + dy * camera.forward.y + dz * camera.forward.z;

    // Behind camera? Skip it
    if (viewZ < 0.01) return null;

    // Perspective divide
    const scale = 1.0 / viewZ;
    const viewX = (dx * camera.right.x + dy * camera.right.y + dz * camera.right.z) * scale;
    const viewY = (dx * camera.up.x + dy * camera.up.y + dz * camera.up.z) * scale;

    // Map to screen pixels
    return {
        x: screenCenterX + viewX * screenWidth,
        y: screenCenterY - viewY * screenHeight,
        scale: scale
    };
}

// Dot product of (object - camera) with camera forward
const toObject = subtract(sphere.position, camera.position);
const dot = dot3(toObject, camera.forward);

if (dot < 0) continue; // Behind camera, skip entirely

const distSq = dx * dx + dy * dy;
const hitRadiusSq = hitRadius * hitRadius;

if (distSq < hitRadiusSq && distSq < closestDistSq) {
    closest = sphere;
    closestDistSq = distSq;
}

[BurstCompile]
public struct SelectionJob : IJobParallelFor {
    [ReadOnly] public NativeArray<float3> positions;
    [ReadOnly] public NativeArray<float> radii;
    [ReadOnly] public float4x4 viewProj;
    [ReadOnly] public float2 mousePos;
    [ReadOnly] public float2 screenSize;

    public NativeArray<float> distancesSq; // Output

    public void Execute(int i) {
        float4 clip = math.mul(viewProj, new float4(positions[i], 1));
        if (clip.w < 0.01f) { distancesSq[i] = float.MaxValue; return; }

        float2 ndc = clip.xy / clip.w;
        float2 screen = (ndc * 0.5f + 0.5f) * screenSize;

        float2 delta = screen - mousePos;
        distancesSq[i] = math.dot(delta, delta);
    }
}
